import React, { useState } from 'react';
import { Link, useNavigate } from 'react-router-dom';
import { SAMPLE_VIDEO } from '../data';

export default function Login({ onLogin }) {
  const navigate = useNavigate();
  const [form, setForm] = useState({ email: '', password: '' });
  const [role, setRole] = useState('student');
  const [error, setError] = useState('');

  const handleChange = (e) =>
    setForm((prev) => ({ ...prev, [e.target.name]: e.target.value }));

  async function handleSubmit(e) {
    e.preventDefault();
    setError('');

    try {
      const res = await fetch('http://localhost:5000/api/auth/login', {
        method: 'POST',
        headers: { 'Content-Type': 'application/json' },
        body: JSON.stringify({
          email: form.email,
          password: form.password,
        }),
      });

      const data = await res.json();
      if (res.ok && data.token) {
        localStorage.setItem('token', data.token);
        localStorage.setItem('user', JSON.stringify(data.user));
        onLogin(data.user);
        navigate(role === 'staff' ? '/staff-dashboard' : '/dashboard');
      } else {
        setError(data.message || 'Invalid email or password');
      }
    } catch {
      setError('Something went wrong. Please try again.');
    }
  }

  const bgColor = role === 'student' ? '#e3f2fd' : '#e8f5e9';
  const themeColor = role === 'student' ? '#1976d2' : '#2e7d32';

  return (
    <div
      className="auth-page"
      style={{
        background: bgColor,
        minHeight: '100vh',
        display: 'flex',
        alignItems: 'center',
        justifyContent: 'center',
        transition: '0.3s ease',
      }}
    >
      <div
        className="auth-card"
        style={{
          background: 'white',
          borderRadius: '16px',
          padding: '40px 50px',
          boxShadow: '0 4px 12px rgba(0,0,0,0.1)',
          width: '400px',
          textAlign: 'center',
        }}
      >
        <h1 style={{ color: themeColor, marginBottom: '10px' }}>
          Welcome to NEXORA
        </h1>

        <div
          style={{
            display: 'flex',
            justifyContent: 'center',
            gap: '12px',
            marginBottom: '25px',
          }}
        >
          <button
            onClick={() => setRole('student')}
            style={{
              background: role === 'student' ? themeColor : '#ccc',
              color: 'white',
              border: 'none',
              borderRadius: '6px',
              padding: '8px 18px',
              cursor: 'pointer',
              fontWeight: 600,
            }}
          >
            Student
          </button>
          <button
            onClick={() => setRole('staff')}
            style={{
              background: role === 'staff' ? themeColor : '#ccc',
              color: 'white',
              border: 'none',
              borderRadius: '6px',
              padding: '8px 18px',
              cursor: 'pointer',
              fontWeight: 600,
            }}
          >
            Staff
          </button>
        </div>

        <form
          className="form"
          onSubmit={handleSubmit}
          style={{ display: 'flex', flexDirection: 'column', gap: '12px' }}
        >
          <input
            className="input"
            name="email"
            placeholder="Email"
            value={form.email}
            onChange={handleChange}
            required
          />
          <input
            className="input"
            name="password"
            type="password"
            placeholder="Password"
            value={form.password}
            onChange={handleChange}
            required
          />
          <button
            type="submit"
            style={{
              background: themeColor,
              color: 'white',
              border: 'none',
              borderRadius: '6px',
              padding: '10px',
              marginTop: '10px',
              cursor: 'pointer',
            }}
          >
            Login
          </button>
          {error && <p style={{ color: 'red', marginTop: '8px' }}>{error}</p>}
          <div style={{ marginTop: '15px', textAlign: 'center' }}>
            <span>New? </span>
            <Link to="/signup" style={{ color: themeColor, fontWeight: 600 }}>
              Create account
            </Link>
          </div>
        </form>
      </div>
    </div>
  );
}
